			}
			value, err := strconv.Atoi(part[slash+1:])
			if err != nil || value <= 0 {
				return errors.New("step must be a positive integer")
			}
			step = value
			part = part[:slash]
		}

		start, end := low, high
		if part != "*" {
			if dash := strings.IndexByte(part, '-'); dash >= 0 {
				left, err := strconv.Atoi(part[:dash])
				if err != nil {
