func doJSON(t *testing.T, router http.Handler, method, target string, body any) *httptest.ResponseRecorder {
	t.Helper()
	var reader *bytes.Reader
	if body != nil {
		raw, err := json.Marshal(body)
		if err != nil {
			t.Fatalf("marshal: %v", err)
		}
		reader = bytes.NewReader(raw)
	} else {
		reader = bytes.NewReader(nil)
	}
	request := httptest.NewRequest(method, target, reader)
	request.Header.Set("Content-Type", "application/json")
	recorder := httptest.NewRecorder()
	router.ServeHTTP(recorder, request)
	return recorder
}

func doRaw(t *testing.T, router http.Handler, method, target, raw string) *httptest.ResponseRecorder {
	t.Helper()
	request := httptest.NewRequest(method, target, strings.NewReader(raw))
	request.Header.Set("Content-Type", "application/json")
	recorder := httptest.NewRecorder()
	router.ServeHTTP(recorder, request)
	return recorder
}

func decodeBody(t *testing.T, recorder *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var body map[string]any
	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatalf("decode %q: %v", recorder.Body.String(), err)
	}
	return body
}

func createTestJob(t *testing.T, router http.Handler, name, expression, timezone string, enabled bool) map[string]any {
	t.Helper()
	recorder := doJSON(t, router, http.MethodPost, "/api/v1/jobs", map[string]any{
		"name": name, "expression": expression, "timezone": timezone, "enabled": enabled,
	})
	if recorder.Code != http.StatusCreated {
		t.Fatalf("create status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	return decodeBody(t, recorder)
}

func assertErrorCode(t *testing.T, recorder *httptest.ResponseRecorder, status int, code string) {
	t.Helper()
	if recorder.Code != status {
		t.Fatalf("status = %d, want %d, body = %s", recorder.Code, status, recorder.Body.String())
	}
	body := decodeBody(t, recorder)
	errorObject, ok := body["error"].(map[string]any)
	if !ok {
		t.Fatalf("body = %s, want error object", recorder.Body.String())
	}
	if errorObject["code"] != code {
		t.Fatalf("code = %v, want %s", errorObject["code"], code)
	}
	if _, hasExtra := errorObject["message"]; !hasExtra {
		t.Fatalf("error object missing message: %s", recorder.Body.String())
	}
	if len(errorObject) != 2 {
		t.Fatalf("error object = %v, want only code and message", errorObject)
	}
}

func TestCreateJobLifecycle(t *testing.T) {
	router, _ := newTestRouter(t)

	before := time.Now().UTC()
	body := createTestJob(t, router, "nightly", "0 9 * * *", "Asia/Shanghai", true)

	for _, key := range []string{"id", "name", "expression", "timezone", "enabled", "created_at", "next_run"} {
		if _, ok := body[key]; !ok {
			t.Fatalf("response missing %s: %v", key, body)
		}
	}
	if body["name"] != "nightly" || body["expression"] != "0 9 * * *" || body["timezone"] != "Asia/Shanghai" {
		t.Fatalf("unexpected identity fields: %v", body)
	}
	if body["enabled"] != true {
		t.Fatalf("enabled = %v, want true", body["enabled"])
	}
	createdAt, err := time.Parse(time.RFC3339, body["created_at"].(string))
	if err != nil {
		t.Fatalf("created_at: %v", err)
	}
	if createdAt.Before(before.Add(-time.Second)) || createdAt.After(time.Now().UTC().Add(time.Second)) {
		t.Fatalf("created_at %s outside processing window", createdAt)
	}
	nextRunRaw, ok := body["next_run"].(string)
	if !ok {
		t.Fatalf("next_run = %v, want string", body["next_run"])
	}
	nextRun, err := time.Parse(time.RFC3339, nextRunRaw)
	if err != nil {
		t.Fatalf("next_run: %v", err)
	}
	if !nextRun.After(before) {
		t.Fatalf("next_run %s must be strictly after processing time %s", nextRun, before)
	}
	// 09:00 Asia/Shanghai is 01:00 UTC on the same calendar day there.
	if nextRun.UTC().Format("15:04") != "01:00" {
		t.Fatalf("next_run utc time = %s, want 01:00", nextRun.UTC().Format("15:04"))
	}

	id := body["id"].(string)
	fetched := doJSON(t, router, http.MethodGet, "/api/v1/jobs/"+id, nil)
	if fetched.Code != http.StatusOK {
		t.Fatalf("get status = %d", fetched.Code)
	}
	if decodeBody(t, fetched)["next_run"] != nextRunRaw {
		t.Fatalf("stored next run differs from create response")
	}
}

func TestDisableAndReenableRecalculatesNextRun(t *testing.T) {
	router, _ := newTestRouter(t)
	created := createTestJob(t, router, "hourly", "0 * * * *", "UTC", true)
	id := created["id"].(string)

	disabled := doJSON(t, router, http.MethodPatch, "/api/v1/jobs/"+id, map[string]any{"enabled": false})
	if disabled.Code != http.StatusOK {
		t.Fatalf("disable status = %d body = %s", disabled.Code, disabled.Body.String())
	}
	disabledBody := decodeBody(t, disabled)
	if disabledBody["enabled"] != false || disabledBody["next_run"] != nil {
		t.Fatalf("disabled job = %v", disabledBody)
	}

	reenabled := doJSON(t, router, http.MethodPatch, "/api/v1/jobs/"+id, map[string]any{"enabled": true})
	if reenabled.Code != http.StatusOK {
		t.Fatalf("reenable status = %d", reenabled.Code)
	}
	reenabledBody := decodeBody(t, reenabled)
	nextRunRaw, ok := reenabledBody["next_run"].(string)
	if !ok {
		t.Fatalf("next_run = %v, want string", reenabledBody["next_run"])
	}
	nextRun, _ := time.Parse(time.RFC3339, nextRunRaw)
	if !nextRun.After(time.Now().Add(-time.Second)) {
		t.Fatalf("recomputed next_run %s not after reenable moment", nextRun)
	}

	renamed := doJSON(t, router, http.MethodPatch, "/api/v1/jobs/"+id, map[string]any{"name": "hourly-renamed"})
	if renamed.Code != http.StatusOK {
		t.Fatalf("rename status = %d", renamed.Code)
	}
	if decodeBody(t, renamed)["name"] != "hourly-renamed" {
		t.Fatalf("rename did not persist: %s", renamed.Body.String())
	}

	deleted := doJSON(t, router, http.MethodDelete, "/api/v1/jobs/"+id, nil)
	if deleted.Code != http.StatusNoContent || deleted.Body.Len() != 0 {
		t.Fatalf("delete status = %d body = %q", deleted.Code, deleted.Body.String())
	}
	assertErrorCode(t, doJSON(t, router, http.MethodGet, "/api/v1/jobs/"+id, nil), http.StatusNotFound, "job_not_found")
}

func TestPatchScheduleAndTimezoneRecalculates(t *testing.T) {
	router, _ := newTestRouter(t)
	created := createTestJob(t, router, "job", "0 9 * * *", "UTC", true)
	id := created["id"].(string)

	updated := doJSON(t, router, http.MethodPatch, "/api/v1/jobs/"+id, map[string]any{
