	assertErrorCode(t, rename, http.StatusUnprocessableEntity, "name_conflict")
}

func TestListPendingJobsWindow(t *testing.T) {
	router, _ := newTestRouter(t)
	inWindow := createTestJob(t, router, "in", "0 0 1 1 *", "UTC", true)
	createTestJob(t, router, "disabled", "0 0 1 1 *", "UTC", false)
	outWindow := createTestJob(t, router, "out", "0 0 31 12 *", "UTC", true)

	inRun, _ := time.Parse(time.RFC3339, inWindow["next_run"].(string))
	outRun, _ := time.Parse(time.RFC3339, outWindow["next_run"].(string))
	if !inRun.Before(outRun) {
		t.Fatalf("in %s should precede out %s", inRun, outRun)
	}

	target := "/api/v1/jobs?state=pending&from=" + inRun.Add(-time.Hour).UTC().Format(time.RFC3339) +
		"&to=" + inRun.Add(time.Hour).UTC().Format(time.RFC3339)
	recorder := doJSON(t, router, http.MethodGet, target, nil)
	if recorder.Code != http.StatusOK {
		t.Fatalf("list status = %d", recorder.Code)
	}
	var jobs []map[string]any
	if err := json.Unmarshal(recorder.Body.Bytes(), &jobs); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(jobs) != 1 || jobs[0]["name"] != "in" {
		t.Fatalf("jobs = %s, want only in", recorder.Body.String())
	}

	// Left-closed: a window starting exactly at next_run includes it.
	startExact := "/api/v1/jobs?from=" + inRun.UTC().Format(time.RFC3339) +
		"&to=" + inRun.Add(time.Hour).UTC().Format(time.RFC3339)
	if recorder := doJSON(t, router, http.MethodGet, startExact, nil); recorder.Code != http.StatusOK {
		t.Fatalf("left-closed status = %d", recorder.Code)
	} else if strings.Count(recorder.Body.String(), "in") != 1 {
		t.Fatalf("left-closed body = %s", recorder.Body.String())
	}

	// Right-open: a window ending exactly at next_run excludes it and returns [].
	endExact := "/api/v1/jobs?from=" + inRun.Add(-time.Hour).UTC().Format(time.RFC3339) +
		"&to=" + inRun.UTC().Format(time.RFC3339)
	if recorder := doJSON(t, router, http.MethodGet, endExact, nil); recorder.Body.String() != "[]" {
		t.Fatalf("right-open body = %s", recorder.Body.String())
	}

	empty := doJSON(t, router, http.MethodGet,
		"/api/v1/jobs?from=2100-01-01T00:00:00Z&to=2100-01-02T00:00:00Z", nil)
	if empty.Code != http.StatusOK || empty.Body.String() != "[]" {
		t.Fatalf("empty window = %d %s", empty.Code, empty.Body.String())
	}
}

